// Extract Files: read the two uploaded HTML reports and turn them into plain text for the agent.
// The form trigger stores uploads as binary data (not in $json); each field label becomes a
// binary key with spaces replaced by underscores, e.g. "P2_Market_Analysis_Report".
const item = $input.first();
const form = item.json;
const helpers = this.helpers;

const category = form['Product Category'] || form.category || 'Area Rug';
const focus = form['Focus Area'] || form.focus || '';
const audience = form['Target Audience'] || 'general Wayfair rug shoppers';
const season = form['Season / Occasion'] || 'the current season';
const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

async function readReport(label) {
  const key = label.replace(/\s+/g, '_');
  if (!item.binary || !item.binary[key]) {
    throw new Error(`No file received for "${label}". Upload the report in the form and try again.`);
  }
  const buffer = await helpers.getBinaryDataBuffer(0, key);
  return buffer.toString('utf8');
}

const stripHtml = (html) => {
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
};

// Up to 40,000 characters per report (about 10k tokens), enough for the full P2 and P3 reports.
const MAX_CHARS = 40000;
const p2Text = stripHtml(await readReport('P2 Market Analysis Report')).slice(0, MAX_CHARS);
const p3Text = stripHtml(await readReport('P3 Competitor Analysis Report')).slice(0, MAX_CHARS);

// Fail loudly instead of letting the agent write a strategy from nothing.
if (p2Text.length < 500) throw new Error(`P2 Market Analysis Report has almost no text (${p2Text.length} characters). Check that you uploaded the right HTML file.`);
if (p3Text.length < 500) throw new Error(`P3 Competitor Analysis Report has almost no text (${p3Text.length} characters). Check that you uploaded the right HTML file.`);

return [{
  json: {
    category,
    focus,
    audience,
    season,
    today,
    p2_content: p2Text,
    p3_content: p3Text
  }
}];

