// Parse Content: turn the agent's answer into the JSON the report expects.
// There is deliberately no fallback content: if the answer can't be used, the run stops
// with an error so a made-up report is never produced.
const input = $input.first().json;
const answer = String(input.output || input.text || '');

let raw = answer.replace(/```json|```/g, '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end <= start) {
  throw new Error('AI Content returned no JSON. Start of its answer: ' + answer.slice(0, 300));
}
raw = raw.slice(start, end + 1);

// Models often put raw line breaks or tabs inside JSON strings, which JSON.parse rejects.
function escapeControlCharsInStrings(s) {
  let out = '', inString = false, escaped = false;
  const chars = Array.from(s);
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    if (inString) {
      if (escaped) { out += ch; escaped = false; continue; }
      if (ch === '\\') { out += ch; escaped = true; continue; }
      if (ch === '"') {
        // A quote only ends the string if JSON syntax follows it (, } ] : or the end).
        // Otherwise it's a stray quote inside the text, e.g. an inch mark in 12" or "quoted words".
        const next = chars.slice(i + 1, i + 40).join('').match(/^\s*(.)/);
        if (!next || ',}]:'.includes(next[1])) { inString = false; out += ch; }
        else out += '\\"';
        continue;
      }
      if (ch === '\n') { out += '\\n'; continue; }
      if (ch === '\r') continue;
      if (ch === '\t') { out += '\\t'; continue; }
      out += ch;
    } else {
      if (ch === '"') inString = true;
      out += ch;
    }
  }
  return out;
}

let content;
try {
  content = JSON.parse(raw);
} catch (e1) {
  try {
    content = JSON.parse(escapeControlCharsInStrings(raw).replace(/,\s*([}\]])/g, '$1'));
  } catch (e2) {
    throw new Error('Could not read the AI answer as JSON (' + e2.message + '). Start of its answer: ' + answer.slice(0, 300));
  }
}

// Strip Markdown the model puts inside values (**bold**, *italic*), since the report shows text as-is.
function cleanMarkdown(v) {
  if (typeof v === 'string') {
    return v.replace(/\*\*([^*]+)\*\*/g, '$1').replace(/__([^_]+)__/g, '$1')
      .replace(/(^|[\s(])\*([^*\s][^*]*?)\*(?=[\s.,;:!?)—–'’"-]|$)/g, '$1$2').replace(/\*\*/g, '').trim();
  }
  if (Array.isArray(v)) return v.map(cleanMarkdown);
  if (v && typeof v === 'object') {
    const o = {};
    for (const [k, val] of Object.entries(v)) o[k] = cleanMarkdown(val);
    return o;
  }
  return v;
}
content = cleanMarkdown(content);

// Fail loudly if the core sections are missing.
const required = ['executive_summary', 'content_ideas', 'social_captions', 'campaigns'];
const missing = required.filter(k => !content[k] || (Array.isArray(content[k]) && content[k].length === 0));
if (missing.length) {
  throw new Error('The AI answer is missing: ' + missing.join(', ') + '. Rerun, or check the AI Content output.');
}

const form = $('Extract Files').first().json;

// Quality check: audit the answer against the reports instead of trusting it.
// Lists banned phrases that slipped through, numbers that don't appear in P2 or P3,
// and past years the reports don't mention, so the category manager can see what to double-check.
const BANNED = ['elevate', 'elevated', 'curated', 'curation', 'seamless', 'seamlessly', 'timeless elegance',
  'must-have', 'game-changer', 'unlock', 'transform your space', 'fast-paced world', 'look no further',
  'stunning', 'shop now', 'buy now', "don't miss out", 'link in bio'];
const answerText = JSON.stringify(content);
const sourceText = (form.p2_content + ' ' + form.p3_content).replace(/,(?=\d{3})/g, '');

const bannedFound = BANNED
  .map(phrase => ({ phrase, count: (answerText.match(new RegExp('\\b' + phrase.replace(/[-']/g, m => '\\' + m) + 's?\\b', 'gi')) || []).length }))
  .filter(b => b.count > 0);

const NUMBER = /\$\s?\d[\d,]*(?:\.\d+)?|\d+(?:\.\d+)?\s?%|\b\d+(?:\.\d+)?x\b|\b\d+\/(?:10|5)\b/g;
const numbers = [...new Set((answerText.match(NUMBER) || []).map(n => n.replace(/\s/g, '')))];
const inSource = n => {
  if (n.includes('/')) return sourceText.includes(n);
  const core = n.replace(/[$,%x]/g, '');
  return new RegExp('(^|[^\\d.])' + core.replace('.', '\\.') + '(?![\\d]|\\.\\d)').test(sourceText);
};
const unsupported = numbers.filter(n => !inSource(n));

// The system message shows real Wayfair lines as style examples; flag any that were reused.
const EXAMPLE_LINES = ['cozy floors start here', 'soft enough for movie nights', 'that rug your friend has',
  'nowhere to be', 'chance of staying in'];
const plainAnswer = answerText.toLowerCase().replace(/[‘’]/g, "'");
const reusedExamples = EXAMPLE_LINES.filter(line => plainAnswer.includes(line));

const thisYear = new Date().getFullYear();
const pastYears = [...new Set((answerText.match(/\b(?:19|20)\d{2}\b/g) || []).filter(y => Number(y) < thisYear && !sourceText.includes(y)))];

const quality = {
  numbersChecked: numbers.length,
  numbersFound: numbers.length - unsupported.length,
  unsupportedNumbers: unsupported,
  bannedPhrases: bannedFound,
  pastYears,
  reusedExamples
};

return [{ json: { content, quality, category: form.category, focus: form.focus, audience: form.audience, season: form.season } }];

const data = $input.first().json;
const c = data.content || {};
const category = data.category || 'Area Rug';
const focus = data.focus || '';
const audience = data.audience || '';
const season = data.season || '';
const qc = data.quality || null;
const today = new Date().toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
// Lists (e.g. carousel slides, email steps) show one per line; line breaks become <br>.
const esc = s => (Array.isArray(s) ? s.join('\n') : String(s || '')).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');

// Quality Check (from Parse Content): what to double-check before publishing
let qualityHtml = '';
if (qc) {
  const reused = qc.reusedExamples || [];
  const clean = !qc.unsupportedNumbers.length && !qc.bannedPhrases.length && !qc.pastYears.length && !reused.length;
  qualityHtml = `
    <section class="section ${clean ? 'qc-ok' : 'qc-warn'}">
      <h2>${clean ? '✅' : '⚠️'} Quality Check</h2>
      <p>An automatic audit of this report against the P2 and P3 reports. It checks that each number appears in a report, not that it is used correctly, so review anything listed here before publishing.</p>
      <ul class="qc-list">
        <li><strong>Numbers:</strong> ${qc.numbersFound} of ${qc.numbersChecked} found in the P2/P3 reports${qc.unsupportedNumbers.length ? '. Not found: ' + qc.unsupportedNumbers.map(esc).join(', ') : ''}</li>
        <li><strong>Banned phrases:</strong> ${qc.bannedPhrases.length ? qc.bannedPhrases.map(b => esc(b.phrase) + ' (' + b.count + ')').join(', ') : 'none'}</li>
        <li><strong>Past years:</strong> ${qc.pastYears.length ? qc.pastYears.join(', ') : 'none'}</li>
        <li><strong>Reused example lines:</strong> ${reused.length ? reused.map(l => "'" + esc(l) + "'").join(', ') : 'none'}</li>
      </ul>
    </section>`;
}

// Key Metrics Cards
const metrics = c.key_metrics || [];
let metricsHtml = metrics.map(m => `
  <div class="insight-card">
    <div class="number">${esc(m.value)}</div>
    <div class="label">${esc(m.label)}</div>
  </div>
`).join('');

// Data Foundation
const df = c.data_foundation || {};
let p2List = (df.p2_insights || []).map(i => `<li>${esc(i)}</li>`).join('');
let p3List = (df.p3_insights || []).map(i => `<li>${esc(i)}</li>`).join('');

// Content Ideas
const ideas = c.content_ideas || [];
let ideasHtml = ideas.map(i => {
  const kws = (i.seo_keywords || []).map(k => `<span class="keyword">${esc(k)}</span>`).join('');
  return `
  <div class="content-card">
    <div class="content-card-header">
      <div class="type">${esc(i.type)}</div>
      <h4>${esc(i.title)}</h4>
    </div>
    <div class="content-card-body">
      <p>${esc(i.description)}</p>
      <div class="data-tag">📊 ${esc(i.data_connection)}</div>
      ${kws ? `<div class="keywords">${kws}</div>` : ''}
    </div>
  </div>`;
}).join('');

// Social Captions
const soc = c.social_captions || {};
let igHtml = (soc.instagram || []).map(p => `
  <div class="social-post">
    <div class="platform-badge ig">Instagram</div>
    <p>${esc(p.caption)}</p>
    <div class="hashtags">${(p.hashtags || []).join(' ')}</div>
  </div>
`).join('');
let pinHtml = (soc.pinterest || []).map(p => `
  <div class="social-post">
    <div class="platform-badge pin">Pinterest</div>
    <p><strong>${esc(p.title)}</strong></p>
    <p>${esc(p.description)}</p>
  </div>
`).join('');
let fbHtml = (soc.facebook || []).map(p => `
  <div class="social-post">
    <div class="platform-badge fb">Facebook</div>
    <p>${esc(p.post)}</p>
  </div>
`).join('');
let ttHtml = (soc.tiktok || []).map(p => `
  <div class="social-post">
    <div class="platform-badge tt">TikTok</div>
    <p><strong>Hook:</strong> ${esc(p.hook)}</p>
    <p>${esc(p.script)}</p>
    ${(p.shot_list || []).length ? `<p><strong>Shot list:</strong></p><ol class="shot-list">${p.shot_list.map(s => `<li>${esc(s)}</li>`).join('')}</ol>` : ''}
  </div>
`).join('');

// Campaigns
const camps = c.campaigns || [];
let campsHtml = camps.map(camp => {
  const det = camp.details || {};
  let detailsHtml = Object.entries(det).map(([k, v]) => `
    <div class="campaign-detail">
      <h5>${k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}</h5>
      <p>${esc(v)}</p>
    </div>
  `).join('');
  return `
  <div class="campaign-card">
    <h4>Campaign: "${esc(camp.name)}"</h4>
    <div class="tagline">"${esc(camp.tagline)}"</div>
    <p>${esc(camp.description)}</p>
    <div class="campaign-details">${detailsHtml}</div>
  </div>`;
}).join('');

// Email Subjects
const emails = c.email_subjects || [];
let emailsHtml = emails.map(e => {
  return `
  <div class="email-subject">
    <span class="icon">${e.icon || '📧'}</span>
    <span class="subject-text">${esc(e.subject)}</span>
  </div>`;
}).join('');

// Competitive Angles
const angles = c.competitive_angles || [];
let anglesHtml = angles.map(a => `
  <div class="competitive-angle">
    <h4>Angle: "${esc(a.title)}"</h4>
    <p><strong>Competitor Gap:</strong> ${esc(a.competitor_gap)}</p>
    <p><strong>Wayfair Opportunity:</strong> ${esc(a.wayfair_opportunity)}</p>
  </div>
`).join('');

// Content Priorities
const priorities = c.content_priorities || [];
let prioritiesHtml = priorities.map(p => {
  const prioClass = p.priority <= 2 ? 'high' : 'medium';
  return `
  <div class="recommendation">
    <div class="priority ${prioClass}">${p.priority}</div>
    <div class="recommendation-content">
      <h4>${esc(p.title)}</h4>
      <p>${esc(p.rationale)}</p>
    </div>
  </div>`;
}).join('');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>AI Insights & Content Report | Wayfair ${esc(category)}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; background: #f8f9fa; }
    .container { max-width: 1100px; margin: 0 auto; padding: 20px; }

    /* Header */
    .header { background: linear-gradient(135deg, #7B2D8E 0%, #5E1A6E 100%); color: white; padding: 40px; border-radius: 12px; margin-bottom: 30px; }
