    .header .subtitle { font-size: 1.2em; opacity: 0.9; }
    .header .meta { margin-top: 20px; display: flex; gap: 15px; flex-wrap: wrap; }
    .header .meta-item { background: rgba(255,255,255,0.15); padding: 8px 16px; border-radius: 20px; font-size: 0.9em; }

