    .campaign-card { background: linear-gradient(135deg, #f8f4fa 0%, #fff 100%); border: 1px solid #e0d4e6; border-radius: 10px; padding: 25px; margin-bottom: 20px; }
    .campaign-card h4 { color: #5E1A6E; font-size: 1.3em; margin-bottom: 8px; }
