    .campaign-details { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; }
    .campaign-detail { background: white; padding: 15px; border-radius: 8px; }
    .campaign-detail h5 { color: #7B2D8E; font-size: 0.9em; margin-bottom: 8px; }
    .campaign-detail p { font-size: 0.9em; color: #555; }

    /* Email Subjects */
    .email-ideas { display: flex; flex-direction: column; gap: 10px; }
    .email-subject { display: flex; align-items: center; gap: 15px; background: #f8f9fa; padding: 15px 20px; border-radius: 8px; }
