    .competitive-angle h4 { color: #5E1A6E; margin-bottom: 12px; }
    .competitive-angle p { margin-bottom: 10px; font-size: 0.95em; }

    /* Priorities */
    .recommendation { display: flex; gap: 20px; margin-bottom: 15px; align-items: flex-start; }
    .priority { width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: bold; font-size: 1.2em; color: white; flex-shrink: 0; }
    .priority.high { background: #7B2D8E; }
    .priority.medium { background: #9B4DB8; }
    .recommendation-content { flex: 1; background: #f8f9fa; padding: 15px 20px; border-radius: 8px; }
    .recommendation-content h4 { color: #5E1A6E; margin-bottom: 8px; }
    .recommendation-content p { font-size: 0.95em; color: #555; }

    /* Footer */
    .footer { background: #5E1A6E; color: white; padding: 30px; border-radius: 12px; text-align: center; margin-top: 30px; }
    .footer .logo { font-size: 1.2em; font-weight: bold; margin-bottom: 10px; }
    .footer p { opacity: 0.9; font-size: 0.9em; margin-top: 5px; }

    @media (max-width: 768px) {
      .data-sources, .content-grid, .social-grid, .campaign-details { grid-template-columns: 1fr; }
      .header .meta { flex-direction: column; gap: 10px; }
      .recommendation { flex-direction: column; gap: 10px; }
      .priority { margin: 0 auto; }
    }
  </style>
</head>
